/**
 * Closed tree for the terms and conditions (ADR-0006). It is rendered by interpolation only: no
 * `innerHTML`, so any HTML inside the CMS text is shown as literal text (REQ-03.16, AC-03.14).
 */

export type TextMark = 'bold' | 'italic' | 'underline' | 'strikethrough' | 'code';
export const TEXT_MARKS: readonly TextMark[] = [
  'bold',
  'italic',
  'underline',
  'strikethrough',
  'code',
];

export interface TermsText {
  readonly kind: 'text';
  readonly text: string;
  readonly marks: readonly TextMark[];
}

export type TermsInline = TermsText;

