    case 'maxLength': {
      const value = numeric(dto.value);
      return value !== null && Number.isInteger(value) && value >= 0 ? { kind, value } : null;
    }
    case 'min':
    case 'max': {
      const value = numeric(dto.value);
      return value === null ? null : { kind, value };
    }
    case 'integer':
      return { kind };
