  if (!isObject(values)) {
    return { value: null, discard: true, warnings: ['[storage] step1 discarded: unexpected shape'] };
  }
  const kept: Record<string, StoredFieldValue> = {};
  const warnings: string[] = [];
  for (const [key, value] of Object.entries(values)) {
