export function screenHeading(config: CountryConfig, screen: WizardScreen): ScreenHeading {
  const group = titleGroup(config, screen);
  return group.status === 'ok'
    ? { kind: 'title', text: group.texts.title }
    : { kind: 'configError', text: config.genericErrorMessage };
}

function titleGroup(config: CountryConfig, screen: WizardScreen): TextGroup<'title'> {
  switch (screen) {
    case 'form':
      return config.texts.formStep;
    case 'plans':
      return config.texts.plansStep;
    case 'summary':
      return config.texts.summaryStep.page;
    case 'confirmation':
      return config.texts.confirmation;
  }
}

