      { vehicleYear: 2018.5, birthDate: '2000-02-30' },
      CO_FACTORS,
      REFERENCE_DATE,
    );
    expect(result.finalPrice).toBe(1_000_000);
  });

  it('AC-02.12 a vehicle from next year uses vehicle age 0', () => {
    const result = computeFinalPrice(100, { vehicleYear: 2027, birthDate: null }, CO_FACTORS, REFERENCE_DATE);
    expect(result.appliedFactors[0]).toEqual({ role: 'vehicleYear', operand: 'vehicleAge', x: 0, multiplier: 1 });
  });

  it('AC-02.13 a band with multiplier 0 is ignored and the remaining valid bands apply', () => {
    const rules = [band('vehicleYear', 0, 10, 0), band('vehicleYear', 6, 10, 1.1)];
    const result = computeFinalPrice(1_000_000, { vehicleYear: 2018, birthDate: null }, rules, REFERENCE_DATE);
    expect(result.finalPrice).toBe(1_100_000);
  });

  it('REQ-02.12 bands with a negative or non-finite multiplier or min > max are discarded', () => {
    const rules = [
      band('vehicleYear', 0, 10, -1),
      band('vehicleYear', 0, 10, Number.POSITIVE_INFINITY),
      band('vehicleYear', 10, 0, 2),
    ];
    const result = computeFinalPrice(1_000, { vehicleYear: 2018, birthDate: null }, rules, REFERENCE_DATE);
    expect(result.finalPrice).toBe(1_000);
    expect(result.appliedFactors).toEqual([]);
  });

  it('REQ-02.12 with overlapping bands the first in the configured order wins', () => {
    const rules = [band('vehicleYear', 0, 10, 1.5), band('vehicleYear', 5, 10, 2)];
    const result = computeFinalPrice(1_000, { vehicleYear: 2018, birthDate: null }, rules, REFERENCE_DATE);
    expect(result.finalPrice).toBe(1_500);
  });

  it('REQ-02.12 a band with an incompatible role and operand is discarded (G3-10)', () => {
    const rules: PriceFactorRule[] = [{ role: 'birthDate', operand: 'vehicleAge', min: 0, max: 100, multiplier: 3 }];
    const result = computeFinalPrice(1_000, { vehicleYear: 2018, birthDate: '2000-05-10' }, rules, REFERENCE_DATE);
    expect(result.finalPrice).toBe(1_000);
  });

  it('REQ-02.11 rounds once at the end, not after each factor', () => {
    // 1 × 1.4 × 1.4 = 1.96 → 2. Rounding after each factor would give 1.
    const rules = [band('vehicleYear', null, null, 1.4), band('birthDate', null, null, 1.4)];
    const result = computeFinalPrice(1, { vehicleYear: 2018, birthDate: '2000-05-10' }, rules, REFERENCE_DATE);
    expect(result.finalPrice).toBe(2);
  });

  it('REQ-02.8 is pure: same inputs give the same output and the rules are not modified', () => {
    const rules = Object.freeze(CO_FACTORS.map((r) => Object.freeze({ ...r })));
    const inputs = Object.freeze({ vehicleYear: 2018, birthDate: '2000-05-10' });
    const first = computeFinalPrice(1_200_000, inputs, rules, REFERENCE_DATE);
    const second = computeFinalPrice(1_200_000, inputs, rules, REFERENCE_DATE);
    expect(second).toEqual(first);
  });

  it('REQ-02.8 depends on the reference date passed in, not on the clock', () => {
    const inputs = { vehicleYear: 2018, birthDate: '2000-05-10' };
    expect(computeFinalPrice(1_200_000, inputs, CO_FACTORS, '2023-01-01').finalPrice).toBe(1_440_000);
    expect(computeFinalPrice(1_200_000, inputs, CO_FACTORS, '2026-11-22').finalPrice).toBe(1_320_000);
  });
});

import { formatPrice } from './format-price';

describe('formatPrice', () => {
  it('AC-02.8 Colombia: "$ 1.320.000" with U+00A0 between "$" and the number', () => {
    const formatted = formatPrice(1_320_000, 'es-CO', 'COP');
    expect(formatted).toBe('$\u00A01.320.000');
    expect(Array.from(formatted, (c) => c.charCodeAt(0).toString(16))).toEqual([
      '24', 'a0', '31', '2e', '33', '32', '30', '2e', '30', '30', '30',
    ]);
  });

  it('AC-02.8 Chile: "$38.985" without separator after "$"', () => {
    expect(formatPrice(38_985, 'es-CL', 'CLP')).toBe('$38.985');
  });

  it('AC-02.8 the price has no decimal part', () => {
    expect(formatPrice(21_589, 'es-CL', 'CLP')).toBe('$21.589');
    expect(formatPrice(1_221_875, 'es-CO', 'COP')).not.toMatch(/,\d/);
  });

  it('REQ-02.6 locale and currency come from the arguments (Strapi), not from code', () => {
    expect(formatPrice(1_000, 'en-US', 'USD')).toBe('$1,000');
  });
});

import { maskDocument } from './mask-document';

describe('maskDocument', () => {
  it.each([
    { value: '1234567890', masked: '******7890' },
    { value: '12.345.678-5', masked: '**.***.678-5' },
    { value: 'E-123456', masked: '*-***456' },
    { value: '12345', masked: '***45' },
    { value: '1234', masked: '**34' },
    { value: '7', masked: '*' },
  ])('AC-03.7 "$value" → "$masked"', ({ value, masked }) => {
    expect(maskDocument(value)).toBe(masked);
  });

  it('AC-03.5 the full Colombian document does not appear in the masked value', () => {
    expect(maskDocument('1234567890')).not.toContain('1234567890');
  });

  it('AC-03.6 the full RUT does not appear and separators are kept', () => {
    const masked = maskDocument('12.345.678-5');
    expect(masked).not.toContain('12.345.678-5');
    expect(masked.replace(/[^.\- ]/g, '')).toBe('..-');
  });

  it('REQ-03.7 spaces are separators and never more than half is shown', () => {
    expect(maskDocument('AB 12')).toBe('** 12');
    expect(maskDocument('')).toBe('');
  });
});

import {
  QUOTE_NUMBER_ALPHABET,
  RandomFill,
  createQuoteNumber,
  cryptoRandomFill,
} from './create-quote-number';

const fixedFill =
  (bytes: readonly number[]): RandomFill =>
  (target) => {
    target.set(bytes.slice(0, target.length));
  };

describe('createQuoteNumber', () => {
  const now = new Date('2026-11-22T10:00:00Z');

  it('AC-03.27 matches ^CO-20261122-[A-HJ-NP-Z2-9]{6}$ with a fixed clock', () => {
    expect(createQuoteNumber('co', now, cryptoRandomFill)).toMatch(/^CO-20261122-[A-HJ-NP-Z2-9]{6}$/);
  });

  it('AC-03.27 the same random source always gives the same number', () => {
    const fill = fixedFill([0, 1, 31, 32, 200, 255]);
    const first = createQuoteNumber('co', now, fill);
    expect(createQuoteNumber('co', now, fill)).toBe(first);
    // 0→A, 1→B, 31→9, 32→A, 200 (8)→J, 255 (31)→9
    expect(first).toBe('CO-20261122-AB9AJ9');
  });

  it('REQ-03.26 uses the UTC date of the payment', () => {
    const lateEveningInBogota = new Date('2026-11-22T23:30:00-05:00');
    expect(createQuoteNumber('cl', lateEveningInBogota, fixedFill([0, 0, 0, 0, 0, 0]))).toBe(
      'CL-20261123-AAAAAA',
    );
  });

  it('REQ-03.26 the alphabet has 32 symbols without 0, O, 1 or I, for every byte value', () => {
    expect(QUOTE_NUMBER_ALPHABET).toHaveLength(32);
    const symbols = new Set<string>();
    for (let byte = 0; byte < 256; byte++) {
      const suffix = createQuoteNumber('co', now, fixedFill([byte, byte, byte, byte, byte, byte])).slice(-6);
      suffix.split('').forEach((s) => symbols.add(s));
    }
    expect([...symbols].sort().join('')).toBe([...QUOTE_NUMBER_ALPHABET].sort().join(''));
    expect([...symbols].some((s) => '0O1I'.includes(s))).toBe(false);
  });
});

