import { CmsRequestError } from './cms-error';
import {
  assembleCountryConfig,
  mapCountryConfig,
  mapCountrySelectionTexts,
  mapCountrySummaries,
  missingTextWarnings,
} from './country-mapper';
import { mapFormFields } from './form-field-mapper';
import { strapiC1, strapiC2, strapiC3, strapiC4, strapiC4Complete } from './testing/strapi-fixtures';

const readyCountry = (data: readonly unknown[] = strapiC3().data) => {
  const result = mapCountryConfig(data, 'co');
  if (result.status !== 'ready') {
    throw new Error('expected a ready country');
  }
  return result;
};

describe('country mapper', () => {
  describe('C1 published countries', () => {
    it('AC-01.5 maps the published countries with the names from Strapi, in the received order', () => {
      expect(mapCountrySummaries(strapiC1().data)).toEqual({
        countries: [
          { code: 'cl', name: 'Chile' },
          { code: 'co', name: 'Colombia' },
        ],
        warnings: [],
      });
    });

    it('REQ-01.7 drops items with an invalid code or without name, and duplicated codes', () => {
      const data = [
        ...strapiC1().data,
        { id: 9, documentId: 'x', code: 'CO', name: 'Upper' },
        { id: 10, documentId: 'y', code: 'pe', name: '  ' },
        { id: 11, documentId: 'z', code: 'co', name: 'Colombia bis' },
        'not an object',
      ];
      const result = mapCountrySummaries(data);
      expect(result.countries.map((c) => c.code)).toEqual(['cl', 'co']);
      expect(result.warnings).toHaveLength(4);
    });
  });

  describe('C2 country selection texts', () => {
    it('REQ-01.2 maps the texts of "/" from Strapi', () => {
      expect(mapCountrySelectionTexts(strapiC2().data)).toEqual({
        heading: 'Cotiza el seguro de tu auto',
        intro: 'Elige tu país para empezar.',
        countryListLabel: 'Países disponibles',
      });
    });

    it('REQ-01.2 intro is optional', () => {
      const data = { ...strapiC2().data, intro: null };
      expect(mapCountrySelectionTexts(data)?.intro).toBeNull();
    });

    it('REQ-01.13 a missing heading or list label is not interpretable (null → error state)', () => {
      expect(mapCountrySelectionTexts({ ...strapiC2().data, heading: ' ' })).toBeNull();
      expect(mapCountrySelectionTexts({ ...strapiC2().data, countryListLabel: null })).toBeNull();
      expect(mapCountrySelectionTexts('nope')).toBeNull();
    });
  });

  describe('C3 country configuration', () => {
    it('REQ-01.1 maps market data and texts of the requested country', () => {
      const result = readyCountry();
      expect(result.country).toEqual({
        code: 'co',
        name: 'Colombia',
        intlLocale: 'es-CO',
        currency: 'COP',
        minimumAge: 18,
      });
      expect(result.genericErrorMessage).toBe('No pudimos mostrar esta sección. Intenta más tarde.');
      expect(result.texts.formStep).toEqual({
        status: 'ok',
        texts: {
          title: 'Tus datos y los de tu vehículo',
          continueLabel: 'Continuar',
          emptyMessage: 'El formulario no está disponible por ahora.',
        },
      });
      expect(result.texts.summaryStep.data).toEqual({
        status: 'ok',
        texts: { editDataLabel: 'Editar datos', yesLabel: 'Sí', noLabel: 'No', emptyValueLabel: '—' },
      });
      expect(missingTextWarnings(result.texts)).toEqual([]);
    });

    it('AC-01.6 no country with that code → notAvailable', () => {
      expect(mapCountryConfig([], 'pe')).toEqual({ status: 'notAvailable' });
    });

    it('REQ-01.4 more than one country with the code is not interpretable', () => {
      const data = strapiC3().data;
      expect(() => mapCountryConfig([...data, ...data], 'co')).toThrow(CmsRequestError);
    });

    it.each([
      ['minimumAge is not an integer', { minimumAge: 17.5 }],
      ['minimumAge is negative', { minimumAge: -1 }],
      ['minimumAge is missing', { minimumAge: null }],
      ['currency is not ISO 4217', { currency: 'PESOS' }],
      ['intlLocale is empty', { intlLocale: '' }],
      ['code does not match', { code: 'cl' }],
    ])('REQ-01.4 invalid market data (%s) is not interpretable', (_case, patch) => {
      const data = [{ ...strapiC3().data[0], ...patch }];
      expect(() => mapCountryConfig(data, 'co')).toThrow(CmsRequestError);
    });

    it('REQ-01.13 without genericErrorMessage the configuration is not interpretable', () => {
      const country = strapiC3().data[0];
      country.wizardTexts.genericErrorMessage = '   ';
      expect(() => mapCountryConfig([country], 'co')).toThrow(CmsRequestError);
    });

    it('AC-01.35 a blank continue text marks the form step as configError, without defaults', () => {
      const country = strapiC3().data[0];
      country.formStepTexts.continueLabel = '';
      const result = readyCountry([country]);
      expect(result.texts.formStep).toEqual({ status: 'configError', missing: ['continueLabel'] });
      expect(result.texts.plansStep.status).toBe('ok');
      expect(missingTextWarnings(result.texts)).toEqual(['[cms] missing texts in formStepTexts: continueLabel']);
    });

    it('REQ-03.38 a missing summary text only breaks its own section', () => {
      const country = strapiC3().data[0];
      Reflect.deleteProperty(country.summaryStepTexts, 'payLabel');
      const result = readyCountry([country]);
      expect(result.texts.summaryStep.payment).toEqual({ status: 'configError', missing: ['payLabel'] });
      expect(result.texts.summaryStep.data.status).toBe('ok');
      expect(result.texts.summaryStep.terms.status).toBe('ok');
    });

    it('REQ-01.13 texts are trimmed', () => {
      const country = strapiC3().data[0];
      country.formStepTexts.title = '  Tus datos  ';
      const formStep = readyCountry([country]).texts.formStep;
      expect(formStep.status === 'ok' && formStep.texts.title).toBe('Tus datos');
    });
  });

  describe('CountryConfig (C3 + C4)', () => {
    it('REQ-01.1 a complete configuration is ready', () => {
      const config = assembleCountryConfig(readyCountry(), mapFormFields(strapiC4Complete().data));
      expect(config.form.status).toBe('ready');
      expect(config.form.fields).toHaveLength(4);
    });

    it('REQ-01.13 a missing step 1 text makes the form configError before empty or unavailable', () => {
      const country = strapiC3().data[0];
      country.formStepTexts.title = '';
      expect(assembleCountryConfig(readyCountry([country]), mapFormFields([])).form.status).toBe('configError');
    });

    it('REQ-01.13 a missing section legend (wizard texts) also makes the form configError', () => {
      const country = strapiC3().data[0];
      country.wizardTexts.vehicleSectionLabel = '';
      const config = assembleCountryConfig(readyCountry([country]), mapFormFields(strapiC4Complete().data));
      expect(config.form.status).toBe('configError');
    });

    it('AC-01.20 the documented C4 example lacks birthDate and documentNumber → unavailable', () => {
      expect(assembleCountryConfig(readyCountry(), mapFormFields(strapiC4().data)).form.status).toBe('unavailable');
    });
  });
});

import { FormFieldConfig } from '../../domain/form/form-config';
import { mapFormFields } from './form-field-mapper';
import { strapiC4, strapiC4Complete } from './testing/strapi-fixtures';

type RawField = Record<string, unknown>;

const field = (overrides: RawField): RawField => ({
  id: 1,
  documentId: 'doc',
  key: 'co_field',
  label: 'Campo',
  type: 'text',
  required: false,
  helpText: null,
  errorMessage: null,
  order: 1,
  section: 'policyholder',
  role: null,
  options: [],
  validations: [],
  ...overrides,
});

/** The three required roles, so tests of other rules see a `ready` form. */
const roleFields = (): RawField[] => strapiC4Complete().data.filter((f) => f.role !== null);

const byKey = (fields: readonly FormFieldConfig[], key: string) => fields.find((f) => f.key === key);

describe('mapFormFields', () => {
  it('REQ-01.8 maps the documented C4 example to the domain', () => {
    const { fields } = mapFormFields(strapiC4().data);
    expect(fields).toEqual([
      {
        key: 'co_documentType',
        label: 'Tipo de documento',
        type: 'select',
        required: true,
        helpText: null,
        errorMessage: 'Elige el tipo de documento.',
        order: 1,
        section: 'policyholder',
        role: null,
        options: [
          { value: 'cc', label: 'Cédula de ciudadanía' },
          { value: 'ce', label: 'Cédula de extranjería' },
        ],
        validations: [],
      },
      {
        key: 'co_vehicleYear',
        label: 'Año del vehículo',
        type: 'number',
        required: true,
        helpText: 'Año del modelo, por ejemplo 2020.',
        errorMessage: 'Ingresa un año válido.',
        order: 3,
        section: 'vehicle',
        role: 'vehicleYear',
        options: [],
        validations: [{ kind: 'integer' }],
      },
    ]);
  });

  it('REQ-01.28 a configuration with the three roles is ready', () => {
    const result = mapFormFields(strapiC4Complete().data);
    expect(result.status).toBe('ready');
    expect(result.warnings).toEqual([]);
  });

  it('AC-01.20 without a field with role birthDate the form is unavailable and warns', () => {
    const data = strapiC4Complete().data.filter((f) => f.role !== 'birthDate');
    const result = mapFormFields(data);
    expect(result.status).toBe('unavailable');
    expect(result.warnings).toContain('[cms] form unavailable: no valid field with role birthDate');
  });

  it('REQ-01.5 no valid field → empty', () => {
    expect(mapFormFields([]).status).toBe('empty');
    expect(mapFormFields([field({ type: 'radio' })]).status).toBe('empty');
  });

  it('AC-01.25 a field with an unknown type and a field without label are skipped with one warning each', () => {
    const data = [
      ...roleFields(),
      field({ key: 'co_unknown', type: 'slider' }),
      field({ key: 'co_noLabel', label: '   ' }),
      field({ key: 'co_ok' }),
    ];
    const result = mapFormFields(data);
    expect(result.fields.map((f) => f.key)).not.toContain('co_unknown');
    expect(result.fields.map((f) => f.key)).not.toContain('co_noLabel');
    expect(byKey(result.fields, 'co_ok')).toBeDefined();
    expect(result.status).toBe('ready');
    expect(result.warnings).toEqual([
      '[cms] form-field skipped: unknown type (key=co_unknown)',
      '[cms] form-field skipped: empty label (key=co_noLabel)',
    ]);
  });

  it('REQ-01.7 an element that is not an object, an invalid key or an unknown section is skipped', () => {
    const data = [...roleFields(), 42, field({ key: 'Bad-Key' }), field({ key: 'co_x', section: 'driver' })];
    const result = mapFormFields(data);
    expect(result.fields).toHaveLength(3);
    expect(result.warnings).toHaveLength(3);
  });

  it('REQ-01.8 orders by fixed section, then order ascending, empty order last, ties by key', () => {
    const data = [
      field({ key: 'v_b', section: 'vehicle', order: 1 }),
      field({ key: 'p_null', section: 'policyholder', order: null }),
      field({ key: 'p_2b', section: 'policyholder', order: 2 }),
      field({ key: 'p_2a', section: 'policyholder', order: 2 }),
      field({ key: 'p_1', section: 'policyholder', order: 1 }),
      field({ key: 'v_a', section: 'vehicle', order: null }),
    ];
    expect(mapFormFields(data).fields.map((f) => f.key)).toEqual(['p_1', 'p_2a', 'p_2b', 'p_null', 'v_b', 'v_a']);
  });

  it('AC-01.10 swapping order in Strapi swaps the fields on screen', () => {
    const before = [field({ key: 'co_b', order: 1 }), field({ key: 'co_c', order: 2 })];
    const after = [field({ key: 'co_b', order: 2 }), field({ key: 'co_c', order: 1 })];
    expect(mapFormFields(before).fields.map((f) => f.key)).toEqual(['co_b', 'co_c']);
    expect(mapFormFields(after).fields.map((f) => f.key)).toEqual(['co_c', 'co_b']);
  });

  it('REQ-01.8 a repeated key keeps the first by order and warns', () => {
    const data = [field({ key: 'co_dup', label: 'Second', order: 5 }), field({ key: 'co_dup', label: 'First', order: 1 })];
    const result = mapFormFields(data);
    expect(result.fields.map((f) => f.label)).toEqual(['First']);
    expect(result.warnings).toContain('[cms] form-field skipped: duplicated key (key=co_dup)');
  });

  it('AC-01.13 select options keep the Strapi order; invalid and repeated values are dropped', () => {
    const data = [
      field({
        key: 'co_make',
        type: 'select',
        options: [
          { id: 1, value: 'marca_a', label: 'Marca A' },
          { id: 2, value: '', label: 'Sin valor' },
          { id: 3, value: 'marca_b', label: 'Marca B' },
          { id: 4, value: 'marca_a', label: 'Repetida' },
          { id: 5, value: 'marca_c', label: ' ' },
        ],
      }),
    ];
    const make = byKey(mapFormFields(data).fields, 'co_make');
    expect(make?.options).toEqual([
      { value: 'marca_a', label: 'Marca A' },
      { value: 'marca_b', label: 'Marca B' },
    ]);
  });

  it('REQ-01.11 a select without valid options is skipped', () => {
    const result = mapFormFields([field({ key: 'co_city', type: 'select', options: [] })]);
    expect(result.fields).toEqual([]);
    expect(result.warnings).toContain('[cms] form-field skipped: select without valid options (key=co_city)');
  });

  it('REQ-01.14 required is true only when Strapi says exactly true', () => {
    const fields = mapFormFields([
      field({ key: 'co_a', required: true }),
      field({ key: 'co_b', required: 'true' }),
      field({ key: 'co_c', required: null }),
    ]).fields;
    expect(fields.map((f) => f.required)).toEqual([true, false, false]);
  });

  it('REQ-01.9 empty help text and error message become null', () => {
    const [mapped] = mapFormFields([field({ helpText: '  ', errorMessage: '' })]).fields;
    expect(mapped.helpText).toBeNull();
    expect(mapped.errorMessage).toBeNull();
  });

  it('REQ-01.15 keeps the validations of the catalog for each type, with decimal values as strings', () => {
    const fields = mapFormFields([
      field({
        key: 'co_plate',
        validations: [
          { id: 1, kind: 'minLength', value: 6, pattern: null },
          { id: 2, kind: 'maxLength', value: '6', pattern: null },
          { id: 3, kind: 'pattern', value: null, pattern: '[A-Z]{3}\\d{3}' },
        ],
      }),
      field({
        key: 'co_amount',
        type: 'number',
        validations: [
          { id: 4, kind: 'min', value: '1.5', pattern: null },
          { id: 5, kind: 'max', value: 10, pattern: null },
          { id: 6, kind: 'integer', value: null, pattern: null },
        ],
      }),
    ]).fields;
    const plate = byKey(fields, 'co_plate');
    expect(plate?.validations.map((v) => v.kind)).toEqual(['minLength', 'maxLength', 'pattern']);
    expect(plate?.validations[1]).toEqual({ kind: 'maxLength', value: 6 });
    expect(byKey(fields, 'co_amount')?.validations).toEqual([
      { kind: 'min', value: 1.5 },
      { kind: 'max', value: 10 },
      { kind: 'integer' },
    ]);
  });

  it('AC-01.15 the pattern is anchored to the whole value', () => {
    const [plate] = mapFormFields([
      field({ validations: [{ id: 1, kind: 'pattern', value: null, pattern: '[A-Z]{3}\\d{3}' }] }),
    ]).fields;
    const rule = plate.validations[0];
    expect(rule.kind).toBe('pattern');
    if (rule.kind === 'pattern') {
      expect(rule.regex.test('ABC123')).toBe(true);
      expect(rule.regex.test('ABC12')).toBe(false);
      expect(rule.regex.test('xABC123')).toBe(false);
      expect(rule.source).toBe('[A-Z]{3}\\d{3}');
    }
  });

  it('REQ-01.15 validations of another type or with invalid parameters are ignored, the field stays', () => {
    const result = mapFormFields([
      field({
        key: 'co_text',
        validations: [
          { id: 1, kind: 'min', value: 1, pattern: null },
          { id: 2, kind: 'pattern', value: null, pattern: '([' },
          { id: 3, kind: 'maxLength', value: -1, pattern: null },
          { id: 4, kind: 'minLength', value: 2.5, pattern: null },
          { id: 5, kind: 'unknownKind', value: 1, pattern: null },
        ],
      }),
      field({ key: 'co_date', type: 'date', validations: [{ id: 6, kind: 'maxLength', value: 3, pattern: null }] }),
      field({
        key: 'co_num',
        type: 'number',
        validations: [
          { id: 7, kind: 'min', value: 10, pattern: null },
          { id: 8, kind: 'max', value: 1, pattern: null },
          { id: 9, kind: 'integer', value: null, pattern: null },
        ],
      }),
    ]);
    expect(byKey(result.fields, 'co_text')?.validations).toEqual([]);
    expect(byKey(result.fields, 'co_date')?.validations).toEqual([]);
    expect(byKey(result.fields, 'co_num')?.validations).toEqual([{ kind: 'integer' }]);
    expect(result.warnings).toContain('[cms] validations min/max ignored: min > max (key=co_num)');
    expect(result.warnings.filter((w) => w.startsWith('[cms] validation ignored'))).toHaveLength(6);
  });

  it('REQ-01.28 a role on an incompatible type is ignored with a warning (and G2-5 applies)', () => {
    const data = strapiC4Complete().data.map((f) => (f.role === 'birthDate' ? { ...f, type: 'text' } : f));
    const result = mapFormFields(data);
    expect(byKey(result.fields, 'co_birthDate')?.role).toBeNull();
    expect(result.warnings).toContain('[cms] form-field role ignored: birthDate is not compatible with text (key=co_birthDate)');
    expect(result.status).toBe('unavailable');
  });

  it('REQ-01.22 several fields with the same role keep it on all of them', () => {
    const data = [...strapiC4Complete().data, field({ key: 'co_documentNumber2', role: 'documentNumber', order: 9 })];
    const result = mapFormFields(data);
    expect(result.fields.filter((f) => f.role === 'documentNumber')).toHaveLength(2);
    expect(result.status).toBe('ready');
  });

  it('REQ-01.7 a non-integer order is treated as empty with a warning', () => {
    const result = mapFormFields([field({ key: 'co_a', order: 1.5 }), field({ key: 'co_b', order: 2 })]);
    expect(result.fields.map((f) => f.key)).toEqual(['co_b', 'co_a']);
    expect(result.warnings).toContain('[cms] form-field order ignored: not an integer (key=co_a)');
  });
});

import { mapPlans } from './plan-mapper';
import { strapiC5 } from './testing/strapi-fixtures';

const COP = { currency: 'COP' };
const plan = (overrides: Record<string, unknown>) => ({ ...strapiC5().data[0], ...overrides });

describe('mapPlans', () => {
  it('REQ-02.3 maps the documented C5 example to the domain', () => {
    expect(mapPlans(strapiC5().data, COP)).toEqual({
      plans: [
        {
          id: 'p0o9i8u7y6t5r4e3w2q1a0s9',
          name: 'Plan Esencial',
          shortDescription: 'Responsabilidad civil y asistencia básica.',
          basePrice: 850000,
          coverages: ['Responsabilidad civil'],
          benefits: ['Grúa 24 h'],
          order: 1,
          recommended: false,
        },
      ],
      warnings: [],
    });
  });

  it('REQ-02.2 a plan that is not active (false or null) is discarded', () => {
    const result = mapPlans([plan({ active: false }), plan({ documentId: 'b', active: null })], COP);
    expect(result.plans).toEqual([]);
    expect(result.warnings).toHaveLength(2);
  });

  it('AC-02.14 a plan with another currency is discarded with a warning', () => {
    const result = mapPlans([plan({ documentId: 'usd', currency: 'USD' }), plan({ documentId: 'cop' })], COP);
    expect(result.plans.map((p) => p.id)).toEqual(['cop']);
    expect(result.warnings).toEqual(['[cms] plan skipped: currency differs from the country currency (id=usd)']);
  });

  it('AC-02.15 a plan without base price is discarded and the others are kept', () => {
    const result = mapPlans([plan({ documentId: 'none', basePrice: null }), plan({ documentId: 'ok' })], COP);
    expect(result.plans.map((p) => p.id)).toEqual(['ok']);
  });

  it.each([
    ['empty name', { name: '  ' }],
    ['base price 0', { basePrice: 0 }],
    ['negative base price', { basePrice: -10 }],
    ['non numeric base price', { basePrice: 'mil' }],
    ['empty documentId', { documentId: '' }],
  ])('REQ-02.25 a malformed plan (%s) is discarded with a warning', (_case, patch) => {
    const result = mapPlans([plan(patch)], COP);
    expect(result.plans).toEqual([]);
    expect(result.warnings).toHaveLength(1);
  });

  it('REQ-02.25 a numeric string base price is accepted', () => {
    expect(mapPlans([plan({ basePrice: '850000' })], COP).plans[0].basePrice).toBe(850000);
  });

  it('REQ-02.3 null coverages or benefits are empty lists and blank labels are omitted', () => {
    const [mapped] = mapPlans(
      [plan({ coverages: null, benefits: [{ id: 1, label: ' ' }, { id: 2, label: 'Grúa' }] })],
      COP,
    ).plans;
    expect(mapped.coverages).toEqual([]);
    expect(mapped.benefits).toEqual(['Grúa']);
  });

  it('REQ-02.4 empty or non-integer order is null; recommended is true only when exactly true', () => {
    const plans = mapPlans(
      [plan({ documentId: 'a', order: null, recommended: true }), plan({ documentId: 'b', order: 2.5, recommended: 'yes' })],
      COP,
    ).plans;
    expect(plans.map((p) => [p.order, p.recommended])).toEqual([
      [null, true],
      [null, false],
    ]);
  });
});

