      'co',
    );
    expect(result.rules[0].multiplier).toBe(1.2);
  });

  it('REQ-02.21 a country unpublished between steps (no data) is an error', () => {
    expect(() => mapPriceFactors([], 'co')).toThrow(CmsRequestError);
  });
});

