function birthdayInYear(birth: CalendarDate, year: number): { month: number; day: number } {
  if (birth.month === 2 && birth.day === 29 && !isLeapYear(year)) {
    return { month: 3, day: 1 };
  }
  return { month: birth.month, day: birth.day };
}

