const fs = require('fs');
const [routesFile, configFile, ...specs] = process.argv.slice(2);
let r = fs.readFileSync(routesFile, 'utf8');
r = r.replace("import { Routes } from '@angular/router';\n",
  "import { EnvironmentProviders, Provider } from '@angular/core';\nimport { RouteReuseStrategy, Routes, provideRouter } from '@angular/router';\n");
r = r.replace("import { countryCaseGuard } from './core/country/country-case-guard';\n",
  "import { countryCaseGuard } from './core/country/country-case-guard';\nimport { CountryRouteReuseStrategy } from './core/country/country-route-reuse-strategy';\n");
r += `
/** Router of the app: the routes plus the per-country reuse strategy. Also used by the tests. */
export function provideAppRouting(): (Provider | EnvironmentProviders)[] {
  return [provideRouter(routes), { provide: RouteReuseStrategy, useClass: CountryRouteReuseStrategy }];
}
`;
fs.writeFileSync(routesFile, r);
let c = fs.readFileSync(configFile, 'utf8');
c = c.replace("import { provideRouter } from '@angular/router';\n", '');
c = c.replace("import { routes } from './app.routes';", "import { provideAppRouting } from './app.routes';");
c = c.replace('provideRouter(routes),', '...provideAppRouting(),');
fs.writeFileSync(configFile, c);
for (const s of specs) {
  let t = fs.readFileSync(s, 'utf8');
  const before = t;
  t = t.replace(/import \{ Router, provideRouter \} from '@angular\/router';/, "import { Router } from '@angular/router';");
  t = t.replace(/import \{ provideRouter \} from '@angular\/router';\n/, '');
  t = t.replace(/import \{ routes \} from '([./]+)app\.routes';/, "import { provideAppRouting } from '$1app.routes';");
  t = t.replace(/provideRouter\(routes\)/g, '...provideAppRouting()');
  fs.writeFileSync(s, t);
  console.log(s, before !== t);
}
