38	/** C1, C3 and C4 for CO and CL as the seed would answer them; other requests stay pending. */
39	export function wizardHandler(content: WizardContent): CmsHandler {
40	  return async (call) => {
41	    const code = countryOf(call);
42	    switch (requestIdOf(call)) {
43	      case 'C1':
44	        return strapiC1().data;
45	      case 'C3':
46	        return code === 'co' ? [content.co] : code === 'cl' ? [clCountryDto()] : [];
47	      case 'C4':
48	        return code === 'co' ? content.coFields : code === 'cl' ? content.clFields : [];
49	      default:
50	        return pending();
51	    }
52	  };
53	}
54	
55	/** Fixed "now": 2026-11-22 12:00 local time (REQ-01.21, ADR-0007). */
56	export const FIXED_NOW = new Date(2026, 10, 22, 12, 0, 0);
57	
58	/**
59	 * Real routes and shell with a fake CMS, in-memory `WIZARD_STORAGE` and a fixed clock (ADR-0007).
60	 */
61	export async function createWizardHarness(patch: Partial<WizardContent> = {}) {
62	  const content: WizardContent = {
63	    co: strapiC3().data[0] as unknown as Record<string, unknown>,
64	    coFields: coFormFieldsDto(),
65	    clFields: clFormFieldsDto(),
66	    ...patch,
67	  };
68	  const cms = new FakeCmsClient();
69	  cms.handler = wizardHandler(content);
70	  const storage = new InMemoryStorage();
71	  TestBed.configureTestingModule({
72	    providers: [
73	      ...provideAppRouting(),
74	      { provide: CmsClient, useValue: cms },
75	      { provide: WIZARD_STORAGE, useValue: storage },
76	      { provide: CLOCK, useValue: () => FIXED_NOW },
77	    ],
78	  });
79	  const harness = await RouterTestingHarness.create();
80	  const root = () => harness.fixture.nativeElement as HTMLElement;
81	  const router = TestBed.inject(Router);
82	
83	  const settle = () => harness.fixture.whenStable();
84	  const open = async (url: string) => {
85	    await harness.navigateByUrl(url);
86	    await settle();
87	  };
88	  const control = <T extends HTMLElement = HTMLInputElement>(key: string) =>
89	    root().querySelector<T>(`#f-${key}`) as T;
90	
91	  /** Types a value like a user: `input` event, then leaves the field (`blur`). */
92	  const fill = async (key: string, value: string, options: { blur?: boolean } = {}) => {
93	    const element = control<HTMLInputElement | HTMLSelectElement>(key);
94	    element.value = value;
95	    element.dispatchEvent(new Event('input'));
96	    if (options.blur ?? true) {
97	      element.dispatchEvent(new Event('blur'));
98	    }
99	    await settle();
100	  };
101	  const check = async (key: string, checked: boolean) => {
102	    const box = control(key);
103	    if (box.checked !== checked) {
104	      box.click();
105	    }
106	    box.dispatchEvent(new Event('blur'));
107	    await settle();
108	  };
109	  const submit = async () => {
110	    root().querySelector<HTMLButtonElement>('button[type="submit"]')?.click();
111	    await settle();
112	    await settle();
113	  };
114	  const storedStep1 = (code: string): unknown => {
115	    const raw = storage.getItem(`ciq.v1.${code}.step1`);
116	    return raw === null ? null : JSON.parse(raw);
117	  };
118	
119	  return {
120	    harness,
121	    cms,
122	    storage,
123	    router,
124	    root,
125	    settle,
126	    open,
127	    control,
128	    fill,
129	    check,
130	    submit,
131	    storedStep1,
132	  };
133	}
134	
135	export type WizardHarness = Awaited<ReturnType<typeof createWizardHarness>>;
