    w.storage.setItem('ciq.v1.co.step1', JSON.stringify({ values: validCoValues() }));
    w.storage.setItem('ciq.v1.co.plan', '{broken');
    await w.open('/co/summary');
    expect(w.router.url).toBe('/co/plans');
  });
});

