input.content:
/* One column at every width; no horizontal scroll from 320 px (REQ-03.36). */
.summary {
  display: grid;
  gap: 1.5rem;
  max-width: 44rem;
}

.summary-section {
  min-width: 0;
  padding: 1rem;
  border: 1px solid #8a8a8a;
  border-radius: 0.5rem;
}

h2 {
  margin: 0 0 0.5rem;
  font-size: 1.125rem;
}

dl {
  margin: 0 0 1rem;
}

.item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 0.5rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid #e0e0e0;
}

dt {
  font-weight: 600;
}

dd {
  margin: 0;
}

.plan-name,
.final-price {
  font-weight: 700;
}

.final-price strong {
  font-size: 1.25rem;
}

.list-title {
  margin: 0.75rem 0 0.25rem;
  font-weight: 600;
}

ul {
  margin: 0;
  padding-left: 1.25rem;
}

/* Inline, scrollable and focusable with the keyboard (REQ-03.16, Q-03.13). */
.terms-region {
  max-height: 16rem;
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
  border: 1px solid #5f5f5f;
  border-radius: 0.25rem;
}

.accept,
.outcome {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

input[type='checkbox'],
input[type='radio'] {
  width: 24px;
  height: 24px;
  margin: 0;
}

.gateway {
  margin: 0 0 1rem;
  padding: 0.75rem;
  border: 1px dashed #5f5f5f;
  border-radius: 0.25rem;
  min-width: 0;
}

.hint {
  margin: 0 0 0.5rem;
  color: #4a4a4a;
}

.pay[aria-disabled='true'] {
  opacity: 0.7;
  cursor: progress;
}

.processing:empty {
  display: none;
}

.processing,
.rejected {
  margin: 0.75rem 0 0;
  font-weight: 600;
}

.rejected {
  color: #b3261e;
}

@media (max-width: 30rem) {
  .item {
    grid-template-columns: 1fr;
    gap: 0;
  }
}

