1	/** State of the simulated payment in the summary. Never persisted (US-03 §6.2). */
2	export type PaymentState = 'idle' | 'processing' | 'rejected';
3	
4	/** Result chosen in the simulated gateway (D9, G2-12). "approved" is the default. */
5	export type PaymentOutcome = 'approved' | 'rejected';
6	
7	export interface PayConditions {
8	  /** Step 1 data shown (texts present). */
9	  readonly dataReady: boolean;
10	  /** The chosen plan is loaded, still available and its price is computed. */
11	  readonly planReady: boolean;
12	  /** Terms loaded with text (not loading, not failed, not unavailable). */
13	  readonly termsReady: boolean;
14	  readonly termsAccepted: boolean;
15	  /** Texts of the payment block present. */
16	  readonly paymentTextsReady: boolean;
17	  readonly payment: PaymentState;
18	}
19	
20	/**
21	 * REQ-03.19: pay is enabled if and only if data and plan are loaded and valid, the terms are
22	 * loaded and accepted, and no payment is in progress. A rejected payment can be retried
23	 * (REQ-03.30).
24	 */
25	export function canPay(c: PayConditions): boolean {
26	  return (
27	    c.dataReady &&
28	    c.planReady &&
29	    c.termsReady &&
30	    c.termsAccepted &&
31	    c.paymentTextsReady &&
32	    c.payment !== 'processing'
33	  );
34	}
35

